export const BODY: string = "\n<p>ضغط صورة إلى 200 كيلوبايت يستغرق نحو دقيقتين. العملية بسيطة، لكن بعض التفاصيل تحدد الفرق بين نتيجة جيدة ونتيجة ممتازة.</p>\n<p>يمر هذا الدليل بكل خطوة. ستجهّز ملف المصدر، وتختار الصيغة الصحيحة، وتنفّذ الضغط، وتراجع النتيجة قبل الرفع.</p>\n<p>يعمل ذلك لصور المدونات وصور المنتجات وصور المحافظ والرفع إلى النماذج، على الهاتف أو الحاسوب.</p>\n<h2 id=\"what-you-need\">ما الذي تحتاجه قبل البدء؟</h2>\n<p>تحتاج إلى الصورة الأصلية بأعلى جودة، ومعرفة حد المنصة والصيغة المقبولة، ومتصفح حديث. هذه الثلاثة تكفي للبدء.</p>\n<p>إذا كانت صورتك من كاميرا احترافية، فهي مثالية للضغط إلى 200 كيلوبايت. الملفات الكبيرة تحمل تفاصيل كثيرة تتحول إلى جودة جيدة عند هذا الحجم.</p>\n<h2 id=\"step-1-open\">الخطوة 1: افتح أداة 200 كيلوبايت</h2>\n<p>افتح <a href=\"/ar/daght-as-sura-ila-200kb/\">أداة ضغط الصورة إلى 200 كيلوبايت</a> في متصفحك. تعمل الأداة بالكامل على جهازك دون رفع الصورة إلى أي خادم.</p>\n<p>لا حاجة إلى حساب أو تثبيت. افتح الصفحة وابدأ فورًا، وستبقى صورتك خاصة طوال العملية.</p>\n<h2 id=\"step-2-upload\">الخطوة 2: ارفع صورتك</h2>\n<p>أسقط صورتك في منطقة الرفع أو اخترها من جهازك. تُقبل ملفات JPG وPNG وWebP وHEIC، بحجم إدخال يصل إلى 25 ميغابايت.</p>\n<p>إذا كانت صورتك ملفًا خامًا من الكاميرا، فحوّله إلى JPG أولًا. الملفات الخام كبيرة جدًا وقد لا تقبلها الأداة مباشرة.</p>\n<h2 id=\"step-3-format\">الخطوة 3: اختر صيغة الإخراج</h2>\n<p>للصور الفوتوغرافية اختر JPG. يعطي جودة ممتازة عند 200 كيلوبايت وتقبله كل المنصات دون استثناء تقريبًا.</p>\n<p>للرسوم والشعارات الشفافة اختر WebP أو PNG. اختيار الصيغة الصحيح يختصر نصف المشكلة ويحسّن النتيجة.</p>\n<h2 id=\"step-4-run\">الخطوة 4: نفّذ الضغط</h2>\n<p>اضغط زر الضغط واترك الأداة تعمل. تبحث تلقائيًا عن أعلى جودة تناسب 200 كيلوبايت، فلا تحتاج إلى تخمين الأرقام.</p>\n<p>تستغرق العملية ثواني معدودة لصورة واحدة. الصور الكبيرة جدًا قد تأخذ وقتًا أطول قليلًا، لكنها تنتهي بسرعة عادة.</p>\n<h2 id=\"step-5-preview\">الخطوة 5: راجع النتيجة بعناية</h2>\n<p>قبل التنزيل، قارن النتيجة بالأصل. كبّر الصورة وافحص التفاصيل المهمة، وتأكد من أن الألوان تبدو صحيحة والحواف نظيفة.</p>\n<p>إذا بدت النتيجة ناعمة أكثر من اللازم، فأعد الضغط من الملف الأصلي مع قص أذكى، لا من النسخة المضغوطة.</p>\n<h2 id=\"step-6-download\">الخطوة 6: نزّل ونظّم</h2>\n<p>نزّل الملف وسمِّه باسم واضح يصف المحتوى، مثل muntaj-ahmar-200kb.jpg. الاسم الواضح يساعد محركات البحث ويسهّل العثور على الملف لاحقًا.</p>\n<p>أنشئ مجلدًا لكل مشروع أو متجر. التنظيم البسيط يمنع استخدام نسخة قديمة في مكان جديد.</p>\n<h2 id=\"fixing-problems\">كيف تحل المشاكل الشائعة؟</h2>\n<p>إذا لم يصل الملف إلى 200 كيلوبايت، فغيّر الصيغة إلى JPG أولًا. PNG هو السبب الأكثر شيوعًا لفشل الوصول إلى الهدف مع الصور الفوتوغرافية.</p>\n<p>وإذا استمرت المشكلة، اسمح بتقليص الأبعاد أو قصّ الصورة بإحكام. كل بكسل تزيله يحرّر مساحة من ميزانية 200 كيلوبايت.</p>\n<h2 id=\"product-photo-workflow\">سير العمل: صورة منتج لمتجر</h2>\n<p>لصورة منتج في متجر، ابدأ بخلفية بيضاء نظيفة وإضاءة جيدة. قصّ الصورة على المنتج نفسه، ثم اضغط إلى 200 كيلوبايت.</p>\n<p>راجع النتيجة بالتكبير على تفاصيل المنتج: الخامة واللون والحواف. إذا بدت واضحة، فالصورة جاهزة للنشر في المتجر.</p>\n<h2 id=\"blog-workflow\">سير العمل: صور المدونة المميزة</h2>\n<p>للصور المميزة في المدونة، اختر صورة عريضة تعبّر عن موضوع المقال. قصّها إلى النسبة المطلوبة، ثم اضغط إلى 200 كيلوبايت.</p>\n<p>استخدم اسم ملف يصف موضوع المقالة. ذلك يساعد محركات البحث على فهم الصورة وربطها بالمحتوى.</p>\n<h2 id=\"phone-workflow\">سير العمل: على هاتفك</h2>\n<p>كل الخطوات تعمل على الهاتف. افتح الأداة في المتصفح وارفع الصورة من معرضك، ثم عاين ونزّل دون نقل الملف إلى حاسوب.</p>\n<p>على الشاشات الصغيرة، استخدم التكبير بإصبعيك لفحص النتيجة. إذا بدت واضحة في التكبير، فهي جاهزة للنشر.</p>\n<h2 id=\"checking-dimensions\">كيف تراجع الأبعاد بعد الضغط؟</h2>\n<p>بعد الضغط، تحقق من الأبعاد النهائية للصورة. بعض المنصات تطلب أبعادًا محددة، مثل 1200 في 630 بكسل لصور المشاركة.</p>\n<p>إذا تغيرت الأبعاد أثناء الضغط، فأعد الضغط مع تثبيت الأبعاد المطلوبة. الأبعاد الصحيحة مهمة بقدر الحجم الصحيح.</p>\n<h2 id=\"infographics-200kb\">الرسوم البيانية والإنفوغرافيك عند 200 كيلوبايت</h2>\n<p>الرسوم البيانية والإنفوغرافيك تحمل نصًا كثيرًا، لذلك تحتاج عناية خاصة عند 200 كيلوبايت. حافظ على الأبعاد كبيرة وخفض الجودة تدريجيًا.</p>\n<p>إذا أصبح النص غير مقروء، فجرّب PNG بدل JPG. الرسوم تتحمل PNG أفضل من الصور الفوتوغرافية، رغم حجمه الأكبر.</p>\n<h2 id=\"social-sharing\">كيف تشارك في وسائل التواصل وصور 200 كيلوبايت؟</h2>\n<p>صور المشاركة في وسائل التواصل تُقص تلقائيًا إلى نسب محددة. اضغط إلى 200 كيلوبايت بالأبعاد الصحيحة لكل منصة لتتجنب قصًا غير مرغوب.</p>\n<p>لفيسبوك وتويتر، استخدم 1200 في 630 بكسل. ولإنستغرام، استخدم مربعًا 1080 في 1080 بكسل.</p>\n<h2 id=\"print-vs-web\">الطباعة مقابل الويب: كيف تعرف ما تحتاجه؟</h2>\n<p>للطباعة تحتاج دقة أعلى بكثير من الويب. صورة 200 كيلوبايت مخصصة للشاشة، واستخدامها للطباعة يعطي نتيجة باهتة.</p>\n<p>القاعدة: إذا كان الهدف ورقًا، فاستخدم الملف الأصلي. وإذا كان الهدف شاشة، فـ200 كيلوبايت كافية وممتازة.</p>\n<h2 id=\"team-standards\">كيف تثبّت معيار 200 كيلوبايت لفريقك؟</h2>\n<p>لفريقك، حدد معيارًا موحدًا: صيغة JPG وهدف 200 كيلوبايت وأبعاد ثابتة لكل نوع صورة. التوحيد يمنع اختلاف النتائج بين أعضاء الفريق.</p>\n<p>شارك مجلدًا مشتركًا للنسخ المضغوطة المعتمدة، حتى لا يعيد كل شخص ضغط الصورة نفسها بإعدادات مختلفة.</p>\n<h2 id=\"troubleshooting-checklist\">قائمة تحقق لحل المشاكل</h2>\n<p>إذا فشل الضغط، فافحص ثلاثة أشياء: الصيغة، والمصدر، والأبعاد. PNG مع صورة فوتوغرافية هو السبب الأول، والمصدر المضغوط أصلًا هو الثاني.</p>\n<p>وإذا كان كل شيء صحيحًا وما زال الهدف بعيدًا، فقصّ الصورة بإحكام أكبر. القص هو أقوى أداة لديك عند الحدود الصعبة.</p>\n<h2 id=\"final-check-200kb\">مراجعة أخيرة قبل الرفع</h2>\n<p>قبل الرفع، تأكد من ثلاثة أشياء: الحجم أقل من 200 كيلوبايت، والصيغة مقبولة، والأبعاد مطابقة لمتطلبات المنصة.</p>\n<p>افتح الملف مرة أخيرة وتأكد من جودته. وللتفاصيل الكاملة، اقرأ <a href=\"/ar/blog/dalil-daght-as-sura-ila-200kb/\">الدليل الكامل لضغط الصورة إلى 200 كيلوبايت</a> ودليل <a href=\"/ar/blog/suwar-200kb-li-bawabat-al-tawzif-wa-al-namadhij/\">صور 200 كيلوبايت لبوابات التوظيف والنماذج</a>، أو انتقل إلى <a href=\"/ar/daght-as-sura-ila-500kb/\">ضاغط 500 كيلوبايت</a> إذا احتجت جودة أعلى.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"كيف أضغط صورة إلى 200 كيلوبايت على هاتفي؟","answer":"نعم. افتح الأداة في متصفح هاتفك وارفع الصورة من معرضك. الضغط يحدث على جهازك، ويمكنك المعاينة والتنزيل دون نقل الملف إلى حاسوب."},{"question":"هل يمكنني ضغط عدة صور إلى 200 كيلوبايت دفعة واحدة؟","answer":"نعم، بأداة الضغط الجماعي. ارفع عشرات الصور دفعة واحدة وحدد هدف 200 كيلوبايت، ثم نزّل النتائج كملف ZIP واحد."},{"question":"لماذا يزن ملفي المنزّل 198 كيلوبايت بدل 200 كيلوبايت بالضبط؟","answer":"لأن 200 كيلوبايت حد أقصى لا هدف دقيق. الأداة تبحث عن أعلى جودة تناسب الحد، فإذا كانت أفضل جودة تنتج 198 كيلوبايت، فهذا هو الملف الصحيح."},{"question":"ماذا أفعل إذا لم تنزل صورتي إلى 200 كيلوبايت؟","answer":"غيّر الصيغة إلى JPG أو WebP أولًا، لأن PNG نادرًا ما يصل إلى 200 كيلوبايت مع الصور المفصلة. ثم اسمح بتقليص الأبعاد أو قصّ الصورة بإحكام أكبر."},{"question":"هل يعمل الضغط إلى 200 كيلوبايت مع لقطات الشاشة؟","answer":"نعم، لكن راجع النص بعد الضغط. لقطات الشاشة تحمل نصًا يحتاج حدة، فحافظ على الأبعاد كبيرة وخفض الجودة تدريجيًا بدل تقليص الأبعاد بقوة."},{"question":"هل يمكنني استخدام صورة 200 كيلوبايت للطباعة؟","answer":"للشاشة نعم، وللطباعة لا. الطباعة تحتاج بكسلات أكثر بكثير، وصورة 200 كيلوبايت ستظهر باهتة على الورق. للطباعة استخدم الملف الأصلي دائمًا."}];
